import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import SpeechRecognition, { useSpeechRecognition } from 'react-speech-recognition';
import './Aibody.css';

const Aibody = () => {
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [inputText, setInputText] = useState("");
    const [isSpeechRecognitionSupported] = useState(SpeechRecognition.browserSupportsSpeechRecognition());
    const { transcript, listening, resetTranscript } = useSpeechRecognition();
    const textareaRef = useRef(null);
    const containerRef = useRef(null);

    useEffect(() => {
        const savedChatHistory = JSON.parse(localStorage.getItem('chatHistory'));
        if (savedChatHistory) {
            setMessages(savedChatHistory);
        }
    }, []);

    useEffect(() => {
        if (messages.length > 0) {
            localStorage.setItem('chatHistory', JSON.stringify(messages));
        }
    }, [messages]);

    const handleToggleListening = async (e) => {
        e.preventDefault();
        if (!listening) {
            SpeechRecognition.startListening({ continuous: true });
        } else {
            SpeechRecognition.stopListening();
            const combinedInput = inputText || transcript;
            if (!combinedInput.trim()) {
                alert("Please say or type something before sending.");
                return;
            } else {
                await fetchApiResponse(combinedInput);
            }
            resetTranscript();
        }
    };

    const fetchApiResponse = async (input) => {
        setLoading(true);
        try {
            const response = await axios.post(`${process.env.REACT_APP_API_URL}/api/v1/search/QueryAnything`, {
                input,
                chatHistory: messages
            }, {
                headers: { 'Content-Type': 'application/json' }
            });

            if (response.data && response.data.chatHistory) {
                setMessages(response.data.chatHistory);
            } else {
                console.error('Unexpected response structure:', response.data);
                setMessages((prevMessages) => [
                    ...prevMessages,
                    { role: 'user', content: input },
                    { role: 'assistant', content: 'Unexpected response format. Please try again.' }
                ]);
            }
        } catch (error) {
            console.error('Error fetching response from API:', error);
            setMessages((prevMessages) => [
                ...prevMessages,
                { role: 'user', content: input },
                { role: 'assistant', content: 'Error fetching response. Please try again.' }
            ]);
        } finally {
            setLoading(false);
            setInputText("");
            resetTranscript();
        }
    };

    const handleTextSubmit = async (e) => {
        e.preventDefault();
        const combinedInput = inputText || transcript;
        if (combinedInput.trim()) {
            await fetchApiResponse(combinedInput);
        } else {
            alert("Please enter or say something before submitting.");
        }
        resetTranscript();
    };

    const handleResetResponses = () => {
        setMessages([]);
        resetTranscript();
        setInputText("");
        localStorage.removeItem('chatHistory');
    };

    useEffect(() => {
        const textarea = textareaRef.current;
        const container = containerRef.current;
        if (textarea && container) {
            const adjustContainerHeight = () => {
                if (textarea.scrollHeight > 48) {
                    container.style.height = `${Math.min(textarea.scrollHeight, 80)}px`;
                } else {
                    container.style.height = '3rem';
                }
            };
            textarea.addEventListener('input', adjustContainerHeight);
            return () => textarea.removeEventListener('input', adjustContainerHeight);
        }
    }, []);

    return (
        <div className="Contain">
            {!isSpeechRecognitionSupported ? (
                <div>Your browser does not support speech recognition. Please use a modern browser.</div>
            ) : (
                <>
                    <div className="nav">
                        <button onClick={handleResetResponses} className="resetbutn">
                            <i className="fa-solid fa-rotate"></i>
                        </button>
                        <h1>Chat AI</h1>
                        <img src="voice1.png" alt="Voice Icon" />
                    </div>

                    {loading ? (
                        <div className="spinner"></div>
                    ) : messages.length === 0 ? (
                        <div className="no-messages">
                            <i className="fa-solid fa-microchip"></i>
                            <p className="typewriter">Hello, How Can I Assist You</p>
                        </div>
                    ) : (
                        <div className="txtresponse">
                            {messages.map((msg, index) => (
                                <div key={index} className={msg.role === "user" ? "user-message" : "assistant-message"}>
                                    <p>{msg.content}</p>
                                </div>
                            ))}
                        </div>
                    )}

                    <form onSubmit={handleTextSubmit}>
                        <div className="respcontainer" ref={containerRef}>
                            <button onClick={handleToggleListening} disabled={inputText.trim().length > 0} className="toggle-listen-btn">
                                {listening ? <i className="fa-solid fa-microphone-slash"></i> : <i className="fa-solid fa-microphone"></i>}
                            </button>
                            <textarea
                                ref={textareaRef}
                                value={inputText || transcript}
                                onChange={(e) => setInputText(e.target.value)}
                                placeholder="Message.."
                                disabled={listening}
                            />
                            <button type="submit" disabled={listening || !inputText.trim()} className="startbutn1">
                                <i className="fa-solid fa-play"></i>
                            </button>
                        </div>
                    </form>
                </>
            )}
        </div>
    );
};

export default Aibody;
